import {walkTime} from './courier-clock-content.mjs';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function walkClock(minute,label='Our model clock'){
 const hour=minute/2,hand=(minute%60)*6;
 return `<svg class="cw-clock" viewBox="0 0 320 320" role="img" aria-label="${esc(label)}: ${walkTime(minute)}. Short hand: hour; long hand: minute." focusable="false" data-cw-minute="${minute}"><circle cx="160" cy="160" r="149" fill="#f3f4e8" stroke="#52765d" stroke-width="3"/><circle cx="160" cy="160" r="139" fill="#fffef8"/>${Array.from({length:12},(_,i)=>`<path d="M160 25V34" stroke="#4c6e59" stroke-width="2" transform="rotate(${i*30} 160 160)"/>`).join('')}${Array.from({length:12},(_,i)=>{const n=i+1,a=n*Math.PI/6;return `<text x="${160+Math.sin(a)*111}" y="${160-Math.cos(a)*111+8}" text-anchor="middle">${n}</text>`;}).join('')}<line x1="160" y1="168" x2="160" y2="94" stroke="#274f40" stroke-width="10" stroke-linecap="round" transform="rotate(${hour} 160 160)" data-cw-hand="hour" data-angle="${hour}"/><line x1="160" y1="173" x2="160" y2="68" stroke="#795b86" stroke-width="5" stroke-linecap="round" transform="rotate(${hand} 160 160)" data-cw-hand="minute" data-angle="${hand}"/><circle cx="160" cy="160" r="6" fill="#274f40"/></svg>`;
}
export function walkTimeline(offset,segments=[]){const x=n=>25+n*310/60;return `<svg class="cw-timeline" viewBox="0 0 360 115" role="img" aria-label="Elapsed minutes from departure. Our marker is at ${offset} minutes on a 0 to 60 minute line. ${segments.map(([a,b])=>`${b-a} minute interval from ${a} to ${b}.`).join(' ')}" focusable="false"><line x1="25" x2="335" y1="62" y2="62" stroke="#365b49" stroke-width="2"/>${Array.from({length:13},(_,i)=>`<path d="M${x(i*5)} 56V68" stroke="#365b49"/>${i%3===0?`<text x="${x(i*5)}" y="91" text-anchor="middle">${i*5}</text>`:''}`).join('')}${segments.map(([a,b],i)=>`<path d="M${x(a)} ${28+i*17}H${x(b)}" stroke="${i?'#795b86':'#a17a2f'}" stroke-width="4"/><text x="${(x(a)+x(b))/2}" y="${21+i*17}" text-anchor="middle">${b-a} min</text>`).join('')}<path d="M${x(offset)} 50l-6 -9h12Z" fill="#795b86" data-cw-marker="${offset}" data-x="${x(offset)}"/><text x="180" y="111" text-anchor="middle">Elapsed minutes from departure</text></svg>`;}
